#include "stdlib/ml/cluster/strided/dkmeansld.h"
#include "stdlib/stats/strided/distances/dsquared_euclidean.h"
#include "stdlib/stats/strided/distances/dcosine_distance.h"
#include "stdlib/stats/strided/distances/dcityblock.h"
#include "stdbool.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/ndarray/base/strides2offset.h"

// Number of cluster statistics:
const int NSTATS = 4; // [ n_obs, sum_squared_dist, mean_squared_dist, stdev_squared_dist ]
const char *METHOD = "lloyd";

/**
* Computes fitted KMeans cluster results for double-precision floating-point strided array data using Lloyd's algorithm.
*
* @param M        number of samples
* @param N        number of features
* @param k        number of clusters
* @param rep      number of times to repeat clustering with different centroids
* @param metric   distance metric
* @param maxIter  maximum number of iterations
* @param tol      relative tolerance before declaring convergence
* @param X        input strided matrix
* @param sx1      stride of the first dimension
* @param sx2      stride of the second dimension
* @param init     strided array containing initial centroid locations
* @param si1      stride of first dimension
* @param si2      stride of second dimension
* @param si3      stride of the third dimension
* @param C        strided array buffer for final centroid locations
* @param sc1      stride of first dimensions of C
* @param sc2      stride of second dimensions of C
* @param stats    strided array buffer for cluster stats
* @param ss1      stride of first dimensions of S
* @param ss2      stride of second dimensions of S
* @param abels   strided array buffer for sample labels
* @param sl       stride of first dimensions of labels
* @param out      output results object
*/
void dkmeansld( const CBLAS_INT M, const CBLAS_INT  N, const CBLAS_INT k, const CBLAS_INT rep, const char *metric, const CBLAS_INT maxIter, const double tol, const double *X, const CBLAS_INT sx1, const CBLAS_INT sx2, const double *init, const CBLAS_INT si1, const CBLAS_INT si2, const CBLAS_INT si3, const double *C, const CBLAS_INT sc1, const CBLAS_INT sc2, const double *stats, const CBLAS_INT ss1, const CBLAS_INT ss2, const double *bestLabels, const CBLAS_INT sl, stdlib_ml_cluster_strided_dkmeans_result out ) {
	CBLAS_INT ox = stdlib_ndarray_strides2offset( 2, (int64_t){ M, N }, (int64_t){ sx1, sx2 } );
	CBLAS_INT oi = stdlib_ndarray_strides2offset( 3, (int64_t){ rep, k, N }, (int64_t){ si1, si2, si3 } );
	CBLAS_INT oc = stdlib_ndarray_strides2offset( 2, (int64_t){ k, N }, (int64_t){ sc1, sc2 } );
	CBLAS_INT os = stdlib_ndarray_strides2offset( 2, (int64_t){ k, NSTATS }, (int64_t){ ss1, ss2 } );
	CBLAS_INT ol = stdlib_ndarray_strides2offset( 1, (int64_t){ M }, (int64_t){ sl } );
	stdlib_strided_dkmeansld_ndarray( M, N, k, rep, metric, maxIter, tol, X, sx1, sx2, ox, init, si1, si2, si3, oi, C, sc1, sc2, oc, stats, ss1, ss2, os, bestLabels, sl, ol, out ); // eslint-disable-line max-len
}

/**
* Computes fitted KMeans cluster results for double-precision floating-point strided array data using Lloyd's algorithm using alternative indexing semantics.
*
*
* @param M        number of samples
* @param N        number of features
* @param k        number of clusters
* @param rep      number of times to repeat clustering with different centroids
* @param metric   distance metric
* @param maxIter  maximum number of iterations
* @param tol      relative tolerance before declaring convergence
* @param X        input strided matrix
* @param sx1      stride of the first dimension
* @param sx2      stride of the second dimension
* @param init     strided array containing initial centroid locations
* @param si1      stride of first dimension
* @param si2      stride of second dimension
* @param si3      stride of the third dimension
* @param C        strided array buffer for final centroid locations
* @param sc1      stride of first dimensions of C
* @param sc2      stride of second dimensions of C
* @param stats    strided array buffer for cluster stats
* @param ss1      stride of first dimensions of S
* @param ss2      stride of second dimensions of S
* @param abels   strided array buffer for sample labels
* @param sl       stride of first dimensions of labels
* @param out      output results object
*/
void API_SUFFIX(stdlib_strided_dkmeansld_ndarray)( const CBLAS_INT M, const CBLAS_INT  N, const CBLAS_INT k, const CBLAS_INT rep, const char *metric, const CBLAS_INT maxIter, const double tol, const double *X, const CBLAS_INT sx1, const CBLAS_INT sx2, const CBLAS_INT ox, const double *init, const CBLAS_INT si1, const CBLAS_INT si2, const CBLAS_INT si3, const CBLAS_INT oi, const double *C, const CBLAS_INT sc1, const CBLAS_INT sc2, const CBLAS_INT oc, const double *stats, const CBLAS_INT ss1, const CBLAS_INT ss2, const CBLAS_INT os, const double *bestLabels, const CBLAS_INT sl, const CBLAS_INT ol, stdlib_ml_cluster_strided_dkmeans_result out ) {
	double (*dist)(const CBLAS_INT, const double*, const CBLAS_INT, const CBLAS_INT, const double*, const CBLAS_INT, const CBLAS_INT);
	double *centroidsNew;
	double bestInertia;
	CBLAS_INT bestIter;
	CBLAS_INT *counts;
	double *labelsOld;
	double *centroids;
	bool strictConv;
	CBLAS_INT bestR;
	CBLAS_INT best;
	CBLAS_INT iter;
	double inertia;
	double *labels;
	CBLAS_INT ocj;
	CBLAS_INT oij;
	CBLAS_INT ixj;
	CBLAS_INT si;
	CBLAS_INT ic;
	CBLAS_INT ix;
	CBLAS_INT ii;
	double shift;
	CBLAS_INT r;
	CBLAS_INT i;
	CBLAS_INT j;
	CBLAS_INT c;
	double d;

	if ( metric == 'euclidean' ) {
		dist = stdlib_strided_dsquared_euclidean_ndarray;
	} else if ( metric == 'cosine' ) {
		dist = stdlib_strided_dcosine_distance_ndarray;    // TODO: change it to dsquared-cosine once implemented
	} else if ( metric == 'cityblock' ) {
		dist = stdlib_strided_dcityblock_ndarray;
	}

	labelsOld = (CBLAS_INT *) malloc( M * sizeof( CBLAS_INT ) );
	labels = (CBLAS_INT *) malloc( M * sizeof( CBLAS_INT ) );
	counts = (CBLAS_INT *) malloc( k * sizeof( CBLAS_INT ) ); // q: sklearn supports sample_weights, should we do the same? if yes, change it to Float64Array
	centroidsNew = (double *) malloc( k*N * sizeof( double ) );
	centroids = (double *) malloc( k*N * sizeof( double ) );

	ii = oi; // start from the offset
	bestInertia = 0.0 / 0.0; // NaN
	for ( r = 0; r < rep; r++ ) {
		gfill( M, -1, labels, 1, 0 );
		gfill( M, -1, labelsOld, 1, 0 );

		strictConv = false;
		for ( iter = 1; iter <= maxIter; iter++ ) {
			gfill( k, 0, counts, 1, 0 ); // How do I fill it with int32 values?
			gfill( k*N, 0, centroidsNew, 1, 0 );

			ix = ox;
			for ( i = 0; i < M; i++ ) {
				best = closestCentroid( dist, N, k, X, sx2, ix, init, si2, si3, ii ); // eslint-disable-line max-len

				labels[ i ] = best;
				counts[ best ] += 1;
				ix += sx1; // move to the next sample
			}

			ix = ox;
			for ( i = 0; i < M; i++ ) {
				c = labels[ i ];
				ic = c * N; // move to starting position of respective centroid in buf
				ixj = ix;
				for ( j = 0; j < N; j++ ) {
					centroidsNew[ ic ] += X[ ixj ]; // accumulate sum of each sample in the cluster
					ic += 1; // move to the next feature of the respective centroid
					ixj += sx2; // move to the next feature of the respective sample
				}
				ix += sx1;
			}

			ic = 0;
			si = ii;
			for ( c = 0; c < k; c++ ) {
				if ( counts[ c ] > 0 ) {
					ocj = ic;
					for ( j = 0; j < N; j++ ) {
						centroidsNew[ ocj ] /= counts[ c ];
						ocj += 1; // move to the next feature of the respective centroid
					}
				} else { // if empty cluster, retain the old features
					ocj = ic;
					oij = si;
					for ( j = 0; j < N; j++ ) {
						centroidsNew[ ocj ] = init[ oij ];
						ocj += 1; // move to the next feature of the respective centroid
						oij += si3; // move to the next feature of the respective centroid's old feature set
					}
				}
				ic += N; // move to the next centroid
				si += si2; // move to the next centroid's old feature set
			}

			ic = 0;
			shift = 0.0;
			si = ii;
			for ( c = 0; c < k; c++ ) {
				oij = si;
				ocj = ic;
				for ( j = 0; j < N; j++ ) {
					d = centroidsNew[ ocj ] - init[ oij ];
					shift += d * d;
					init[ oij ] = centroidsNew[ ocj ];  // update init for next iteration
					ocj += 1;
					oij += si3;
				}
				ic += N;
				si += si2;
			}
			dlacpy( 'all', k, N, centroidsNew, N, 1, 0, centroids, N, 1, 0 );

			// We know stride for labels is `1` and offset is `0`, so this method for similarity checking works
			if ( shift < tol || isEqualArray( labels, labelsOld ) ) {
				strictConv = true;
				break;
			}
			gcopy( M, labels, 1, 0, labelsOld, 1, 0 );
		}

		// re-run E-step
		if (!strictConv) {
			ix = ox;
			for ( i = 0; i < M; i++ ) {
				best = closestCentroid( dist, N, k, X, sx2, ix, init, si2, si3, ii ); // eslint-disable-line max-len
				labels[ i ] = best;
				ix += sx1; // move to the next sample
			}
		}

		inertia = computeInertia( dist, M, N, X, sx1, sx2, ox, centroids, N, 1, 0, labels ); // eslint-disable-line max-len
		if ( isnan( bestInertia ) || inertia < bestInertia ) {
			gcopy( M, labels, 1, 0, bestLabels, sl, ol );
			dlacpy( 'all', k, N, centroids, N, 1, 0, C, sc1, sc2, oc );
			bestInertia = inertia;
			bestR = r;
			if ( iter > maxIter ) {
				bestIter = maxIter;
			} else {
				bestIter = iter;
			}
		}
		ii += si1; // move to the next replicate
	}

	out.rep = rep;
	out.replicate = bestR;
	out.metric = metric;
	out.iterations = bestIter;
	out.method = METHOD;
	out.inertia = bestInertia;
	out.k = k;
	out.samples = M;
	out.features = N;

	free( labelsOld );
	free( labels );
	free( counts );
	free( centroidsNew );
	free( centroids );
}
